// CQ fetch is automatically triggered when head != tail and CQ is enabled
IDLE: begin

    if (cqcsr_en_i) begin

        // CQ was recently enabled by SW. Set cq_head, cqmf, cmd_ill, cmd_to and fence_w_ip to zero
        if (!cq_en_q) begin
            cq_head_o           = '0;
            cqcsr_mf_wen_o      = 1'b1;
            cqcsr_to_wen_o      = 1'b1;
            cqcsr_ill_wen_o     = 1'b1;
            cqcsr_fence_wen_o   = 1'b1;

            cq_en_n = 1'b1;
        end

        // New command
        else if ((cq_tail_i & idx_mask) != cq_head_i) begin
            cq_pptr_n = {cqb_ppn_i[PPNW-1:0], 12'b0} | ({{PLEN-32{1'b0}}, cq_head_i} << 4);
            state_n = FETCH;
        end
    end

    // Check if EN signal was recently cleared by SW
    else if (cq_en_q) begin
        cq_en_n = 1'b0;
    end
end

FETCH: begin
    mem_req_o.ar_valid = 1'b1;
    if (mem_resp_i.ar_ready) begin
        state_n     = REGISTER;
    end
end

REGISTER: begin
    if (mem_resp_i.r_valid) begin
        mem_req_o.r_ready   = 1'b1;
        if (mem_resp_i.r.last) begin
            cmd_n[127:64]   = mem_resp_i.r.data[((64*1) &
                                    (RVIOMMUCfg.AxiDataWidth-1))+:64];
            cq_head_o       = (cq_head_i + 1) & idx_mask;
            state_n         = DECODE;
        end
        else cmd_n[63:0]    = mem_resp_i.r.data[((64*0) &
                                    (RVIOMMUCfg.AxiDataWidth-1))+:64];

        // Check for AXI transmission errors
        if (mem_resp_i.r.resp != axi_pkg::RESP_OKAY) begin
            state_n         = ERROR;
            cqcsr_mf_o      = 1'b1;
            cqcsr_mf_wen_o  = 1'b1;
        end
    end
end

rv_iommu::IOTINVAL: begin

    iotinval_o.av       = cmd_iotinval.av;
    iotinval_o.gv       = cmd_iotinval.gv;
    iotinval_o.pscv     = cmd_iotinval.pscv;
    iotinval_o.vpn      = cmd_iotinval.addr[(rv_iommu::GPPNW39-1):0];
    iotinval_o.gscid    = cmd_iotinval.gscid;
    iotinval_o.pscid    = cmd_iotinval.pscid;

    // From Spec:
    // A command is determined to be illegal if a reserved bit is set to 1
    // Setting PSCV to 1 with IOTINVAL.GVMA is illegal
    if ((|cmd_iotinval.reserved_1) || (|cmd_iotinval.reserved_2)                        ||
        (|cmd_iotinval.reserved_3) || (|cmd_iotinval.reserved_4)                        ||
        (cmd_iotinval.func3 != rv_iommu::VMA && cmd_iotinval.func3 != rv_iommu::GVMA)   ||
        (cmd_iotinval.func3 == rv_iommu::GVMA && cmd_iotinval.pscv)) begin

        cqcsr_ill_o     = 1'b1;
        cqcsr_ill_wen_o = 1'b1;
        state_n         = ERROR;
    end

    // Check func3 to determine if command is VMA or GVMA
    else if (cmd_iotinval.func3 == rv_iommu::VMA) begin
        iotinval_o.inval_vma    = 1'b1;
    end

    else if (cmd_iotinval.func3 == rv_iommu::GVMA) begin
        iotinval_o.inval_gvma   = 1'b1;
    end

rv_iommu::IOFENCE: begin

    // From Spec:
    // A command is determined to be illegal if a reserved bit is set to 1
    if ((|cmd_iofence.reserved_1) || (|cmd_iofence.reserved_2)  ||
        (cmd_iofence.func3 != rv_iommu::IOFENCE_C)) begin
        cqcsr_ill_o     = 1'b1;
        cqcsr_ill_wen_o = 1'b1;
        state_n         = ERROR;
    end

    // Valid IOFENCE.C command
    else begin

        // TODO: Add IOFENCE support with PR and PW using R/W counters

        // From Spec:
        // If AV=1, the IOMMU writes DATA to memory at a 4-byte aligned address ADDR[63:2] * 4
        if(cmd_iofence.av) begin
            cq_pptr_n   = {cmd_iofence.addr[PLEN-1-2:0], 2'b0};
            wr_state_n  = AW_REQ;
            state_n     = WRITE;
        end

        // Set cqcsr.fence_w_ip if IOMMU supports and uses WSIs
        if (cmd_iofence.wsi && wsi_en_i) begin
            cqcsr_fence_o       = 1'b1;
            cqcsr_fence_wen_o   = 1'b1;
        end

        // Wait for ATS invalidations to complete before proceeding.
        if(atsinval_inflight_i) begin
           ats_fence_valid_o = 1'b1;
           // The ATS synch request has completed.
           if(ats_fence_ready_i) begin
              state_n = IDLE;
           // An Invalidation timed out.
           end else if(atsinval_to_i) begin
              cqcsr_to_o = 1'b1;
              cqcsr_to_wen_o = 1'b1;
           // Wait for invalidations to complete.
           end else begin
              state_n = DECODE;
           end
        end

    end

// Write DATA (32-bit) to ADDR[63:2] * 4
WRITE: begin

    unique case (wr_state_q)
        AW_REQ: begin
            mem_req_o.aw_valid  = 1'b1;
            if (mem_resp_i.aw_ready) begin
                wr_state_n  = W_DATA;
            end
        end
        W_DATA: begin
            mem_req_o.w_valid   = 1'b1;
            if(mem_resp_i.w_ready) begin
                wr_state_n  = B_RESP;
            end
        end
        B_RESP: begin
            if (mem_resp_i.b_valid) begin
                mem_req_o.b_ready   = 1'b1;
                if (mem_resp_i.b.resp != axi_pkg::RESP_OKAY) begin
                    state_n         = ERROR;
                    cqcsr_mf_o      = 1'b1;
                    cqcsr_mf_wen_o  = 1'b1;
                end
                else state_n = IDLE;
            end
        end
        default: state_n = IDLE;
    endcase

// Leaf first-stage PTE
STAGE_1: begin

    final_gpa = {pte.ppn[rv_iommu::GPPNW39-1:0], iova_q[11:0]};

    // superpages
    if (main_lvl_q == LVL2)
        final_gpa[20:0] = iova_q[20:0];
    if (main_lvl_q == LVL1)
        final_gpa[29:0] = iova_q[29:0];
    else begin
        pf_excep_n  = 1'b1;
        state_n     = ERROR;
    end

// Command queue config
task automatic iommu_cq_init();
   // Local variables for 64-bit and 32-bit data
   logic [63:0] cqb_val;
   logic [31:0] cqh_val;
   logic [31:0] reg_data;
   // Compute the value for the command-queue base register:
   //   cqb_val = ( (COMMAND_QUEUE_BASE >> 2) & CQB_PPN_MASK ) | CQ_LOG2SZ_1;

   cqb_val = (((COMMAND_QUEUE_BASE >> 2) & CQB_PPN_MASK) | CQ_LOG2SZ_1);

   // Program the 64-bit cqb register using two 32-bit writes.
   axi_single_write_prog(IOMMU_CQB_ADDR, cqb_val[31:0]);
   axi_single_write_prog(IOMMU_CQB_ADDR + 4, cqb_val[63:32]);

   // Read the current command-queue head (cqh) using the programming interface.
   axi_single_read_prog(IOMMU_CQH_ADDR, cqh_val);
   // Set cqt (tail) equal to cqh.
   axi_single_write_prog(IOMMU_CQT_ADDR, cqh_val);

   // Enable the command queue by writing (CQCSR_CQEN | CQCSR_CIE) to cqcsr.
   axi_single_write_prog(IOMMU_CQCSR_ADDR, (CQCSR_CQEN | CQCSR_CIE));

   // Poll until the CQON bit is set in the cqcsr register.
   do begin
     axi_single_read_prog(IOMMU_CQCSR_ADDR, reg_data);
     @(posedge axi_tr_drv.axi.clk_i);
   end while ((reg_data & CQCSR_CQON) == 0);
endtask

// Write a 128-bit command into the command queue
task automatic rv_iommu_write_command_in_queue(ref cq_entry_t inval_i);
   logic [31:0] cqt;
   logic [31:0] cq_entry_addr;
   // Read the current command-queue tail index (cqt)
   axi_single_read_prog(64'h24, cqt);

   // Compute the address of the next CQ entry:
   // Each entry is 16 bytes (2×64-bit words) so we shift cqt by 4 bits.
   cq_entry_addr = (COMMAND_QUEUE_BASE & CQ_PPN_MASK32) | (cqt << 4);

   // Write the first 64-bit word at the computed command queue address.
   mem_write(cq_entry_addr,      inval_i[63:0]);
   mem_write(cq_entry_addr + 8,  inval_i[127:64]);

   // Increment the command-queue tail pointer and program it back.
   cqt = cqt + 1;
   axi_single_write_prog(64'h24, cqt);
endtask
